const aliasIndex=new Map();
const aliasAmbiguities=new Map();
for(const p of hashAll){
 const names=['PN G'+p.id, 'PNG '+p.id,'HASH '+p.hashId, p.name, p.hashName,...(p.aliases||[])];
 p.searchAliases=[...new Set(names.filter(Boolean))];
 for(const name of p.searchAliases){const key=normalizePNQuery(name);if(!key)continue;
   if(!aliasIndex.has(key))aliasIndex.set(key,[]);
   const values=aliasIndex.get(key);if(!values.includes(p))values.push(p);
 }
}
for(const [k,v] of aliasIndex)if(v.length>1)aliasAmbiguities.set(k,v.map(p=>p.id));
function aliasesMatch(p,query){
 const q=normalizePNQuery(query);if(!q)return true;
 // Exact catalogued identifier first. If ambiguous, show each matched object.
 const matches=aliasIndex.get(q);
 if(matches)return matches.includes(p);
 return p.searchAliases.some(a=>normalizePNQuery(a).includes(q));
}
