const CATALOG_LABELS={M:['Messier','Messier'],Caldwell:['Caldwell','Caldwell'],NGC:['NGC','NGC'],IC:['IC','IC'],Abell:['Abell','Abell'],Sh2:['Sharpless','Sharpless'],Minkowski:['Minkowski','Minkowski'],Henize:['Henize','Henize'],Kohoutek:['Kohoutek','Kohoutek'],Longmore:['Longmore','Longmore'],Weinberger:['Weinberger','Weinberger'],PHR:['PHR / MASH','PHR / MASH'],MPA:['MPA','MPA'],BMP:['BMP','BMP'],IPHASX:['IPHASX','IPHASX'],Kn:['Kn','Kn'],Pa:['Pa','Pa'],JaSt:['JaSt','JaSt'],PK:['PK','PK']};
