 +0.000062*sDeg(141.74+53.303771*k)+0.000060*sDeg(207.14+2.453732*k)+0.000056*sDeg(154.84+7.306860*k)+0.000047*sDeg(34.52+27.261239*k)+0.000042*sDeg(207.19+0.121824*k)+0.000040*sDeg(291.34+1.844379*k)+0.000037*sDeg(161.72+24.198154*k)+0.000035*sDeg(239.56+25.513099*k)+0.000023*sDeg(331.55+3.592518*k);
