 link.href='https://chatgpt.com/?q='+encodeURIComponent(prompt);link.classList.remove('disabled');link.removeAttribute('aria-disabled');
 link.textContent=lang==='ja'?'GPTに撮影相談 ↗':'Ask GPT for imaging advice ↗';
 link.title=lang==='ja'?'新しいChatGPT画面にこのPNの撮影相談を引き継ぎます':'Open ChatGPT with details of the selected PN';
 science.href='https://chatgpt.com/?q='+encodeURIComponent(pnSciencePrompt(p));science.classList.remove('disabled');science.removeAttribute('aria-disabled');
 science.textContent=lang==='ja'?'GPTに科学的解説を依頼 ↗':'Ask GPT for scientific background ↗';
 science.title=lang==='ja'?'選択した天体の性質・研究史を資料に基づいて解説':'Open ChatGPT for a literature-based scientific explanation';
