function qaWarning(p){
 const f=SIMBAD_QA_FLAGS[p.id];if(!f)return '';
 let msg='';
 if(f.kind==='type')msg=lang==='ja'?('SIMBAD分類：'+f.otype+'（HASH：'+(hashStatusLabel[p.hashStatus]||p.hashStatus)+'）．SIMBAD側の分類がPNと異なるため，その追加別名は保留中です．中心星・別天体の可能性は個別に要確認．'):('SIMBAD class: '+f.otype+' (different from HASH PN). SIMBAD-only aliases held pending validation.');
 else if(f.kind==='duplicate')msg=lang==='ja'?'SIMBADの同一天体が複数のHASHレコードへ対応．追加別名は保留中です．':'One SIMBAD object corresponds to multiple HASH records; aliases held.';
 else msg=lang==='ja'?'SIMBADの対応候補について座標・分類条件の不一致があり，追加別名は保留中です．':'SIMBAD cross-identification is unresolved; aliases held.';
 return '<div class="qa-warning" role="note"><strong>'+(lang==='ja'?'SIMBAD名称照合：要確認':'SIMBAD cross-ID: review needed')+'</strong><div>'+escapeHTML(msg)+'</div></div>';
}
function renderPNInfo(p){
const preferred=primaryPNName(p), otherAliases=p.aliases.filter(a=>a!==preferred);
// Alternate names are sourced only from HASH representative names and retained cross-IDs.

const searchUrl='https://www.astrobin.com/search/?q='+encodeURIComponent(preferred);
renderObservation(p);
const photoAstrobin=$('photoAstrobin');photoAstrobin.href=searchUrl;photoAstrobin.textContent=tr('astrobin')+' ↗';photoAstrobin.style.display='inline-block';
const fields=[[tr('detailAngular'),Number.isFinite(p.major)?arcLabel(p.major)+(Number.isFinite(p.minor)?' × '+arcLabel(p.minor):''):p.theta?arcLabel(2*p.theta):'–'],[tr('detailDistance'),Number.isFinite(p.d)?rnd(p.d,3)+' kpc<br><span class="small">(+'+rnd(p.distE,3)+' / −'+rnd(p.diste,3)+' kpc)</span>':(lang==='ja'?'–（HASHに距離データなし）':'– (distance not available in HASH)')],[tr('detailSurface'),rnd(logHbetaSurfaceBrightness(p),2)+'<br><span class="small">erg s⁻¹ cm⁻² arcsec⁻²（log₁₀）</span>'],[tr('detailHbeta'),rnd(p.M,2)],[tr('detailPosition'),rnd(p.x,3)+' / '+rnd(p.y,3)+' / '+rnd(p.z,3)+' kpc'],[lang==='ja'?'赤経・赤緯（J2000）':'RA / Dec (J2000)',
  '<span class="coord-line">RA '+escapeHTML(sexagesimalRA(p.ra))+'</span><br>'+
  '<span class="coord-line">Dec '+escapeHTML(sexagesimalDec(p.dec))+'</span>']];
const eqrows=equipments.map((e,i)=>{const z=sizePixels(p,e);return '<tr data-setup="'+i+'"><td>'+escapeHTML(e.name)+'</td><td class="pixel-scale">'+prettyNumber(z.scale,3)+'″/px</td></tr>'}).join('');
const simbadURL='https://simbad.cds.unistra.fr/simbad/sim-id?Ident='+encodeURIComponent('PN G'+p.id);
const catalogAuditLinks='<p class="small" style="margin:7px 0 10px">'+(p.hashStatus?'<b>HASH '+hashStatusLabel[p.hashStatus]+' · ID '+p.hashId+'</b>'+(p.morph?' · Morph: '+escapeHTML(p.morph+p.morphSub):'')+'<br>':'')+
 (ACKER_1992_PAGES[p.id]?' · Strasbourg–ESO 1992: '+(lang==='ja'?'PDF '+ACKER_1992_PAGES[p.id]+'ページ':'PDF p. '+ACKER_1992_PAGES[p.id]):'')+
 ' · <a href="'+simbadURL+'" target="_blank" rel="noopener noreferrer">SIMBAD ↗</a> · '+
 '<a href="https://hashpn.space/" target="_blank" rel="noopener noreferrer">HASH PN ↗</a></p>';
$('focus').innerHTML=qaWarning(p)+(otherAliases.length?'<p class="pn-alias">'+(lang==='ja'?'別名：':'Other names: ')+escapeHTML(otherAliases.join(' / '))+'</p>':'')+catalogAuditLinks+
'<dl class="pn-details-grid">'+fields.map(([k,v])=>'<div class="pn-field"><dt>'+escapeHTML(k)+'</dt><dd>'+v+'</dd></div>').join('')+'</dl>';
$('pnPixels').hidden=false;
$('pnPixelResults').innerHTML=equipments.length?'<table class="pixel-table"><thead><tr><th style="width:62%">'+escapeHTML(tr('pixelName'))+'</th><th style="width:38%">'+escapeHTML(tr('pixelScale'))+'</th></tr></thead><tbody>'+eqrows+'</tbody></table>':'<p class="small">'+escapeHTML(tr('noEquipment'))+'</p>';
 
 bindFovHover(p);refreshSaveButton();updateGPTConsult(p);
}
