 const sphere=ctx.createRadialGradient(cx-R*.35,cy-R*.32,R*.07,cx+R*.08,cy+R*.05,R*1.18);
 sphere.addColorStop(0,'#1b3855');sphere.addColorStop(.65,'#10273f');sphere.addColorStop(1,'#061223');
 ctx.fillStyle=sphere;ctx.fill();ctx.clip();
 // Equatorial graticule, drawn over the visible hemisphere only.
 for(let dec=-60;dec<=60;dec+=30){const path=[];for(let ra=0;ra<=360;ra+=3)path.push([ra,dec]);skyLine(path,'rgba(100,147,193,.26)',.75)}
