// A reader-friendly, provenance-aware classification. The original scientific
// determination is preserved in pn.status for source review; these public labels
// do not claim that an extragalactic survey class is a HASH classification.
function dsoPNPublicStatus(pn){
 const raw=String(pn?.status||'').trim();
 const hash=dsoPNMatch(pn)?.hashStatus ||
   (/HASH\s*[:：]\s*True/i.test(raw)?'T':/HASH\s*[:：]\s*Likely/i.test(raw)?'L':/HASH\s*[:：]\s*Possible/i.test(raw)?'P':null);
 const isJa=lang==='ja';
 if(hash==='T')return isJa?'True（確定・HASH）':'True (confirmed by HASH)';
 if(hash==='L')return isJa?'Likely（有力候補・HASH）':'Likely (probable, HASH)';
 if(hash==='P')return isJa?'Possible（候補・HASH）':'Possible (candidate, HASH)';
 if(/PN候補棄却|PNではないと判定|非PN|候補棄却/.test(raw))
   return isJa?'PNではない可能性（研究で再判定）':'Unlikely to be a PN (study reassessment)';
 if(/原表Hフラグ|混入疑い|H II領域等の混入/.test(raw))
   return isJa?'Possible（別種の天体が混じる可能性）':'Possible (may be another type of object)';
 if(/分光確認PN|分光でPNを確認|分光確認されたPN|分光確認との記載あり/.test(raw))
   return isJa?'分光観測で確認（研究）':'Spectroscopically confirmed (study)';
 if(/星団との所属を強く示唆/.test(raw))return isJa?'星団への所属は有力（研究）':'Likely cluster membership (study)';
 if(/(?:^|[^a-z])likely_PN|PN有力候補|PN所属確率>90%/.test(raw))
   return isJa?'Likely（有力候補・研究）':'Likely (probable candidate, study)';
 if(/(?:^|[^a-z])possible_PN/.test(raw))
   return isJa?'Possible（候補・研究）':'Possible (candidate, study)';
 if(/PN候補|PN様|中心星候補|候補/.test(raw))
   return isJa?'Possible（候補・研究）':'Possible (candidate, study)';
 if(/PN分類|PN（|PN.S検出|PN検出|分光観測|PN・|PNを検出|星団内PN検出|^PN$/.test(raw))
   return isJa?'惑星状星雲として報告（研究）':'Reported as PN (study)';
 return isJa?'確認状況は不明':'Identification status not established';
}
// Keep the PN selector compact; detailed evidence and provenance remain below.
