 const key=dsoImageKey(p,kind,pn)+':'+mode;
 const card=$(kind==='host'?'dsoHostCard':'dsoPNCard');if(!card)return;
 const msg=card.querySelector('.dso-image-message');
 const retry=card.querySelector('.dso-image-retry');
