function bindDSOPlanning(p){
 for(const [id,original] of [['dsoObsLat','obsLat'],['dsoObsLon','obsLon'],['dsoObsUTC','obsUTC']]){
  const input=$(id);if(!input)continue;
  input.addEventListener('change',()=>{const other=$(original);if(other){other.value=input.value;other.dispatchEvent(new Event('change',{bubbles:true}));}});
 }
 const reset=$('dsoObsReset');if(reset)reset.addEventListener('click',()=>$('obsReset').click());
 const locate=$('dsoObsLocate');if(locate)locate.addEventListener('click',()=>pnmapGeolocate(locate));
 renderDSOObservation(p);
 renderDSOFraming(p);
}

// Independent persistent DSO selection list (PN saved list remains unchanged).
const DSO_SAVED_STORAGE='pnmap_selected_dso_names_v1';
let dsoSavedNames=new Set();
try{const parsed=JSON.parse(localStorage.getItem(DSO_SAVED_STORAGE)||'[]');
 if(Array.isArray(parsed))dsoSavedNames=new Set(parsed.filter(x=>typeof x==='string'&&dsoData.some(p=>p['DSO名']===x)));
}catch(e){}
function dsoStoreSaved(){try{localStorage.setItem(DSO_SAVED_STORAGE,JSON.stringify([...dsoSavedNames]))}catch(e){}}
function dsoRefreshSavedButton(){
 const p=dsoData[dsoSelectedIndex],b=$('dsoSaveSelected');if(!p||!b)return;
 const selected=dsoSavedNames.has(p['DSO名']);b.textContent=selected?tr('removeFromList'):tr('addToList');
 b.setAttribute('aria-pressed',String(selected));
}
function dsoToggleSaved(){
 const p=dsoData[dsoSelectedIndex];if(!p)return;
 const name=p['DSO名'];if(dsoSavedNames.has(name))dsoSavedNames.delete(name);else dsoSavedNames.add(name);
 dsoStoreSaved();dsoRefreshSavedButton();dsoRenderSavedList();
 const status=$('dsoSaveStatus');if(status)status.textContent=tr(dsoSavedNames.has(name)?'listSaved':'listRemoved');
}
function dsoRenderSavedList(){
 const host=$('dsoSavedItems'),counter=$('dsoSavedCount');if(!host||!counter)return;
 const selected=dsoData.filter(p=>dsoSavedNames.has(p['DSO名']));counter.textContent='（'+selected.length+'）';
 host.replaceChildren();
 if(!selected.length){host.textContent=lang==='ja'?'まだDSOは追加されていません．':'No DSOs saved yet.';dsoRefreshSavedButton();return;}
 for(const p of selected){
  const row=document.createElement('div');row.className='saved-row';
  const target=document.createElement('button');target.className='saved-target';target.type='button';
  target.textContent=dsoVal(p['DSO名'],DSO_NAME_EN)+(p['別名']?' / '+dsoVal(p['別名'],DSO_ALIAS_EN):'');
  target.onclick=()=>{
   // As in the PN list, selecting a saved item opens its details regardless of
   // whether it currently passes the display-condition filters.
   if(!dsoVisible.some(x=>x.index===p.index)){
    dsoSelectedIndex=p.index;dsoInspectorInitialized=true;renderDSODetails();
    if(p.coords){skyCenterRA=p.coords.ra;skyCenterDec=p.coords.dec;}
    schedule();
    if(typeof isMobileLayout==='function'&&isMobileLayout())$('dsoInspector').scrollIntoView({block:'start',behavior:'smooth'});
   }else selectDSO(p.index,true);
  };
  const remove=document.createElement('button');remove.className='saved-delete';remove.type='button';
  remove.textContent=lang==='ja'?'消去':'Remove';
  remove.setAttribute('aria-label',(lang==='ja'?'リストから削除 ':'Remove ')+p['DSO名']);
  remove.onclick=()=>{dsoSavedNames.delete(p['DSO名']);dsoStoreSaved();dsoRenderSavedList();dsoRefreshSavedButton();};
  row.append(target,remove);host.append(row);
 }
 dsoRefreshSavedButton();
}
function dsoExportTable(chosen){
 const headers=['DSO name','Aliases','DSO type','Environment','RA J2000 (deg)','Dec J2000 (deg)','RA J2000 (hms)','Dec J2000 (dms)','Meridian altitude (deg)','Major diameter (arcmin)','Minor diameter (arcmin)','Diameter source','Individual PN records','Individual PN positions','Reference URL'];
 const setups=equipments.map(e=>({name:e.name,scale:dsoFovScale(e)}));
 for(const setup of setups){headers.push('DSO major diameter (px) — '+setup.name,'DSO minor diameter (px) — '+setup.name,'FOV major-side occupancy (%) — '+setup.name,'FOV minor-side occupancy (%) — '+setup.name);}
 const rows=chosen.map(p=>{
  const size=dsoAngularSize(p),records=dsoRecordPNs.get(p.index)||[],pos=p.coords;
  const result=[p['DSO名'],(lang==='en'?dsoVal(p['別名']||'',DSO_ALIAS_EN):p['別名']||''),(lang==='en'?dsoCompactTypeLabel(p):p['分類']||''),(lang==='en'?dsoVal(p['所属銀河・環境']||'',DSO_ENV_EN):p['所属銀河・環境']||''),pos?.ra??'',pos?.dec??'',pos?.raString||'',pos?.decString||'',pos&&Number.isFinite(pos.dec)? +(90-Math.abs(obsPlace.lat-pos.dec)).toFixed(3):'',size?.major??'',size?.minor??'',size?.source||'',records.length,records.filter(x=>dsoPNCoords(x)).length,p['参考文献・取得先']||''];
  for(const setup of setups){
   const dims=equipments.find(e=>e.name===setup.name);
   const w=Number(dims?.width),h=Number(dims?.height);
   const fw=setup.scale*w/60,fh=setup.scale*h/60;
   result.push(size?+(size.major*60/setup.scale).toFixed(2):'',size?+(size.minor*60/setup.scale).toFixed(2):'',size&&w>0&&h>0?+(size.major/Math.max(fw,fh)*100).toFixed(2):'',size&&w>0&&h>0?+(size.major/Math.min(fw,fh)*100).toFixed(2):'');
  }
  return result;
 });
 return {headers,rows};
}
function dsoStellariumDesignation(p){
 return String(p['DSO名']||'').replace(/^(M|NGC|IC)(?=\d)/,'$1 ');
}
function dsoExportSol(chosen,filename){
 const observable=chosen.filter(p=>p.coords&&Number.isFinite(p.coords.ra)&&Number.isFinite(p.coords.dec));
 if(!observable.length)throw Error(lang==='ja'?'J2000座標を持つDSOがありません．':'No DSO has a J2000 position.');
 const dt=new Date(),now=dt.getFullYear()+'-'+String(dt.getMonth()+1).padStart(2,'0')+'-'+String(dt.getDate()).padStart(2,'0')+' '+String(dt.getHours()).padStart(2,'0')+':'+String(dt.getMinutes()).padStart(2,'0')+':'+String(dt.getSeconds()).padStart(2,'0');
 const olud='{'+('10000000-1000-4000-8000-'+String(Math.floor(Math.random()*0xffffffffffff)).padStart(12,'0'))+'}';
 const entry={name:'Saved DSOs',description:'Selected DSOs exported from PNmap. Coordinates are representative J2000 centers.',
  'creation date':now,'last edit':now,objects:observable.map(p=>({designation:dsoStellariumDesignation(p),name:p['DSO名'],type:p['分類']==='銀河系内の星団'?'Star cluster':'Galaxy',ra:sexagesimalRA(p.coords.ra),dec:sexagesimalDec(p.coords.dec),fov:0,jd:0,isVisibleMarker:true})),sorting:''};
 downloadBlob(JSON.stringify({version:'2.1',shortName:'Observing list for Stellarium',defaultListOlud:'',observingLists:{[olud]:entry}},null,2),filename,'application/json;charset=utf-8');
 return observable.length;
}
function dsoExportSavedList(){
 const chosen=dsoData.filter(p=>dsoSavedNames.has(p['DSO名'])),status=$('dsoSavedStatus');
 if(!chosen.length){status.textContent=tr('listEmpty');return;}
 try{
  const fmt=$('dsoSavedExportFormat').value,filename='deep_sky_objects_saved_'+chosen.length;
  let count=chosen.length;
  if(fmt==='sol')count=dsoExportSol(chosen,filename+'.sol');
  else if(fmt==='csv')exportCsv(dsoExportTable(chosen),filename+'.csv');
  else if(fmt==='xlsx')exportXlsx(dsoExportTable(chosen),filename+'.xlsx');
  else throw Error('Unknown export format');
  status.textContent=count+' '+tr('items')+' — '+tr('exportDone')+(count<chosen.length?(lang==='ja'?'（座標未登録の'+(chosen.length-count)+'件はSOLから除外）':' ('+(chosen.length-count)+' without coordinates excluded from SOL)'):'');
 }catch(err){status.textContent=(lang==='ja'?'出力に失敗しました：':'Export failed: ')+String(err.message||err);}
}
