function selectDSO(index,focus=false){
 if(!dsoData[index])return;
 const changed=index!==dsoSelectedIndex;
 dsoSelectedIndex=index;dsoInspectorInitialized=true;
 if(changed||!$('dsoPNInfo'))renderDSODetails();
 renderDSOList();
 if(focus){const pos=dsoData[index].coords;if(pos){skyCenterRA=pos.ra;skyCenterDec=pos.dec;}}
 schedule();
 if(focus&&typeof isMobileLayout==='function'&&isMobileLayout())$('dsoInspector').scrollIntoView({block:'start',behavior:'smooth'});
}
function drawDSOSky(){
 // Render the same celestial globe, graticule, constellations, and gestures as sky mode.
 drawSky([]);
 dsoMapPoints=[];
 const R=globeRadius(),cx=width/2,cy=height/2;
 for(const row of dsoVisible){
  if(!row.coords)continue;
  const v=skyProj(row.coords.ra,row.coords.dec);
  if(!v.front||!Number.isFinite(v.sx)||Math.hypot(v.sx-cx,v.sy-cy)>R+2)continue;
  dsoMapPoints.push({...v,index:row.index,row});
 }
 for(const p of dsoMapPoints){
  const isSelected=p.index===dsoSelectedIndex;
  const color='#a4c2da'; // All DSO host types share one marker color.
  ctx.beginPath();ctx.arc(p.sx,p.sy,isSelected?6:4.5,0,2*Math.PI);ctx.fillStyle=color;ctx.fill();
  ctx.strokeStyle='#08192a';ctx.lineWidth=1;ctx.stroke();
  if(isSelected){ctx.beginPath();ctx.arc(p.sx,p.sy,11,0,2*Math.PI);ctx.strokeStyle='#fff0a1';ctx.lineWidth=2;ctx.stroke();}
 }
 const selected=dsoMapPoints.find(v=>v.index===dsoSelectedIndex);
 if(selected){const labelText=dsoVal(selected.row['DSO名'],DSO_NAME_EN);ctx.font='12px system-ui';ctx.lineWidth=3;ctx.strokeStyle='#08192a';ctx.strokeText(labelText,selected.sx+10,selected.sy-11);ctx.fillStyle='#fff1b6';ctx.fillText(labelText,selected.sx+10,selected.sy-11);}
}
function dsoHitTest(evt){
 const bb=canvas.getBoundingClientRect(),x=evt.clientX-bb.left,y=evt.clientY-bb.top;
 let best=null,ds=17*17;
 for(const p of dsoMapPoints){const d=(p.sx-x)**2+(p.sy-y)**2;if(d<ds){ds=d;best=p}}
 return best;
}
