    const dx=e.clientX-dragX,dy=e.clientY-dragY;
    if(Math.hypot(e.clientX-dragStartX,e.clientY-dragStartY)>5)dragMoved=true;
    if(dragMoved){if(projectionMode==='sky'||projectionMode==='dso'){skyCenterRA=mod(skyCenterRA+(skyViewpoint==='inside'?dx:-dx)*.30/skyZoom,360);skyCenterDec=clamp(skyCenterDec+dy*.30/skyZoom,-89,89)}else{az+=dx*.008;el=clamp(el+dy*.008,-Math.PI*.49,Math.PI*.49)}schedule()}
