// sufficiently bright H-beta surface, and a suitable new moon <=3 months away.
// Apply/reapply recomputes altitude relative to observer location; it does not
// overwrite observer coordinates or the user's equipment/saved-PN list.
const FAVORITE_FILTERS_STORAGE='pn3d_favorite_display_filters_v1';
const DISPLAY_FILTER_IDS=['diamLow','diamHigh','sbLow','sbHigh','altLow','altHigh','moonLow','moonHigh','search','bright','maxDist','maxErr','range','rankSort'];
const DISPLAY_DEFAULTS={diamLow:'0',diamHigh:'1000',sbLow:'-18',sbHigh:'-10',altLow:'-90',altHigh:'90',moonLow:'0',moonHigh:'14',search:'',bright:'surface',maxDist:'30',maxErr:'100',range:String(zoomToSlider(4)),rankSort:'diameter',rings:true,catalogMode:'multi',catalogs:[]};
