 headers.push(...setups.map(x=>x.col));
 headers.push('Source URL');
 const rows=objects.map(p=>{
   const first=primaryPNName(p);
   return [p.hashId??'',p.hashStatus??'','PN G'+p.id,first,p.aliases.filter(a=>a!==first).join(' / '),p.ra,p.dec,+transitAltitude(p).toFixed(3),p.l,p.b,+(Number.isFinite(p.major)?p.major:2*p.theta).toFixed(3),p.d,p.distE,p.diste,p.logF,logHbetaSurfaceBrightness(p),p.M,p.x,p.y,p.z,...equipments.map(eq=>+(sizePixels(p,eq).pix).toFixed(2)),'https://doi.org/10.1051/0004-6361/202347519'];
 });
